import json
G=[[3]*23 for _ in range(17)]
source=[[2,3,3,6,7],[0,4,4,2,2],[2,6,0,4,3],[3,3,7,7,6],[3,3,2,3,3]]
# Keep source motif as-is; markers are motif center anchors.
for i,row in enumerate(source):
 for j,v in enumerate(row):
  if v!=3:G[5+i][5+j]=v
centers=[(4,19),(5,13),(9,20),(13,7),(14,17)]
for cr,cc in centers:
 for i in range(5):
  for j in range(5):
   v=source[i][j]
   if v!=3:G[cr+i-2][cc+j-2]=v
assert len(G)==17 and all(len(row)==23 for row in G)
print(json.dumps({'action':'submit','grid':G},separators=(',',':')))

